import os, re, json, sys
from urllib.parse import unquote

SITE = 'site'
SKIP = {'index.html', 'sobre.html', 'contato.html'}

files = [f for f in os.listdir(SITE) if f.lower().endswith('.html')]
disk_lower = {f.lower(): f for f in files}

pages = {}   # disk filename -> {h1, tema, sin:[], ana:[]}
no_tema = []
for f in sorted(files):
    if f in SKIP:
        continue
    html = open(os.path.join(SITE, f), encoding='utf-8').read()
    m_h1 = re.search(r'<h1>(.*?)</h1>', html)
    m_tema = re.search(r'<p class="tema">Tema:\s*(.*?)</p>', html)
    if not m_tema:
        no_tema.append(f)
        continue
    sin, ana = [], []
    m_sec = re.search(r'<section id="sinonimos">.*?</section>', html, re.S)
    if m_sec:
        sin = re.findall(r'href="([^"]+)"', m_sec.group(0))
    m_sec = re.search(r'<section id="analogas">.*?</section>', html, re.S)
    if m_sec:
        ana = re.findall(r'href="([^"]+)"', m_sec.group(0))
    pages[f] = {'h1': m_h1.group(1).strip() if m_h1 else None,
                'tema': m_tema.group(1).strip(), 'sin': sin, 'ana': ana}

